// waybar/style.css — wholesale regen. The seven roles become @define-color
// vars in a header block; every rule references them, so a re-theme only
// rewrites the header values. The tray-recolor rule appears only when enabled.

use crate::theme::{hash, Theme};

pub fn render(t: &Theme) -> String {
    let p = &t.palette;
    let mut s = String::new();

    s.push_str(
        "/* Minimal muted-olive waybar — generated by lifeconf.\n\
         \x20  Edit ~/.config/lifeconf/theme.toml (or run `lifeconf`), not this file. */\n\n",
    );

    // Role palette. Everything below references these names.
    s.push_str(&format!("@define-color bg {};\n", hash(&p.bg)));
    s.push_str(&format!("@define-color surface {};\n", hash(&p.surface)));
    s.push_str(&format!("@define-color border {};\n", hash(&p.border)));
    s.push_str(&format!("@define-color text {};\n", hash(&p.text)));
    s.push_str(&format!("@define-color accent {};\n", hash(&p.accent)));
    s.push_str(&format!("@define-color warn {};\n", hash(&p.warn)));
    s.push_str(&format!("@define-color urgent {};\n\n", hash(&p.urgent)));

    s.push_str(&format!(
        "* {{\n\
         \x20 font-family: \"{}\", \"Cousine Nerd Font\", \"GoMono Nerd Font\", \"NotoSansM Nerd Font\", monospace;\n\
         \x20 font-size: {}px;\n\
         \x20 min-height: 0;\n\
         \x20 border: none;\n\
         \x20 border-radius: 0;\n\
         }}\n\n",
        t.font.family, t.font.size
    ));

    s.push_str(
        "window#waybar {\n\
         \x20 background: @bg;\n\
         \x20 color: @text;\n\
         \x20 border-bottom: 1px solid @border;\n\
         }\n\n\
         #workspaces button {\n\
         \x20 padding: 0 8px;\n\
         \x20 margin: 0;\n\
         \x20 color: @text;\n\
         \x20 background: transparent;\n\
         \x20 box-shadow: none;\n\
         }\n\n\
         #workspaces button.active {\n\
         \x20 color: @accent;\n\
         \x20 box-shadow: inset 0 -2px @accent;\n\
         }\n\n\
         #workspaces button.urgent {\n\
         \x20 color: @urgent;\n\
         }\n\n\
         #workspaces button:hover {\n\
         \x20 color: @accent;\n\
         \x20 background: @surface;\n\
         }\n\n\
         #window,\n\
         #clock,\n\
         #custom-notif,\n\
         #custom-dnd,\n\
         #idle_inhibitor,\n\
         #network,\n\
         #pulseaudio,\n\
         #wireplumber,\n\
         #backlight,\n\
         #battery,\n\
         #cpu,\n\
         #memory,\n\
         #tray {\n\
         \x20 padding: 0 10px;\n\
         \x20 color: @text;\n\
         }\n\n\
         #clock {\n\
         \x20 color: @accent;\n\
         }\n\n\
         #pulseaudio.muted,\n\
         #wireplumber.muted {\n\
         \x20 color: @urgent;\n\
         }\n\n\
         #custom-dnd {\n\
         \x20 color: @urgent;\n\
         }\n\n\
         /* Caffeine held: idle chain inhibited. */\n\
         #idle_inhibitor.activated {\n\
         \x20 color: @warn;\n\
         }\n\n\
         #network.disconnected {\n\
         \x20 color: @urgent;\n\
         }\n\n\
         /* Load warnings (thresholds set in config.jsonc). */\n\
         #cpu.warning,\n\
         #memory.warning {\n\
         \x20 color: @warn;\n\
         }\n\n\
         #cpu.critical,\n\
         #memory.critical {\n\
         \x20 color: @urgent;\n\
         }\n\n\
         /* Laptop modules (macbook variant; ignored on the desktop bar). */\n\
         #battery.charging,\n\
         #battery.plugged {\n\
         \x20 color: @accent;\n\
         }\n\n\
         #battery.warning {\n\
         \x20 color: @warn;\n\
         }\n\n\
         #battery.critical {\n\
         \x20 color: @urgent;\n\
         }\n\n\
         tooltip {\n\
         \x20 background: @surface;\n\
         \x20 border: 1px solid @border;\n\
         \x20 color: @text;\n\
         }\n",
    );

    // Note: there is deliberately NO tray-icon recolor. GTK3/waybar here rejects
    // `-gtk-icon-filter` (and doesn't support the CSS `filter` property), so any
    // such rule is a hard parse error that blanks the whole bar. Tray icons keep
    // their apps' own colours.

    s
}
